css:
[data-chat-header] { border-bottom: 1px solid #e1e5ed !important; background: #fff !important; }
[data-workspace-area="conversation"] { background: radial-gradient(ellipse at 85% 0%, rgba(2,54,173,.045), transparent 55%), #f7f8fa !important; }
[data-slot="composer-host"] { border: 1px solid #d9e1ef !important; border-radius: 14px !important; box-shadow: 0 5px 24px rgba(2,54,173,.06) !important; background: #fff !important; }
[data-user-message-bubble] { border: 1px solid #d8e3fb !important; border-radius: 14px !important; }
[data-slot="sidebar"] [data-thread-item] { border-radius: 7px !important; }
[data-slot="sidebar"] [data-thread-item][aria-current="page"] { box-shadow: inset 3px 0 0 #fff; }
[data-thread-details-card], [data-slot="settings-group"] { border: 1px solid #e1e5ed !important; border-radius: 12px !important; box-shadow: 0 2px 10px rgba(20,40,80,.025); }
.chat-markdown a { color: #0236ad; text-underline-offset: 3px; }
[data-slot="sidebar"] svg.lucide { stroke-width: 1.7; }
/* Keep light-mode text utilities readable on the cobalt sidebar. */
[data-slot="sidebar"], [data-slot="sidebar-inner"] { --foreground: #ffffff; --muted-foreground: #c3d3f5; --secondary-foreground: #ffffff; --accent-foreground: #ffffff; color: #ffffff !important; }
[data-slot="sidebar"] :is(a,button,span,p,h1,h2,h3,input,svg), [data-slot="sidebar-inner"] :is(a,button,span,p,h1,h2,h3,input,svg) { color: #ffffff !important; }
[data-slot="sidebar"] :is(small,time), [data-slot="sidebar-inner"] :is(small,time) { color: #c3d3f5 !important; }
[data-slot="sidebar"] input::placeholder, [data-slot="sidebar-inner"] input::placeholder { color: #c3d3f5 !important; }
[data-slot="sidebar"] [data-slot="project-monogram"], [data-slot="sidebar-inner"] [data-slot="project-monogram"] { color: #ffffff !important; background: #285bc6 !important; }

/* Teravera's official inverse wordmark; separate from navigation controls. */
[data-slot="sidebar-inner"]::before {
  content: "";
  display: block;
  flex: 0 0 72px;
  min-height: 72px;
  width: 100%;
  box-sizing: border-box;
  background-image: url("data:image/svg+xml;base64,");
  background-repeat: no-repeat;
  background-position: 20px center;
  background-size: 170px auto;
  border-bottom: 1px solid rgba(255,255,255,.18);
  pointer-events: none;
}
